import { styled, Text, View } from '@tamagui/web';

import type { DividerContract } from './Divider.contract';
import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { prependClassName } from '../../helpers/prependClassName';
import type { WebDivRef, WebElementProps, WebHrRef } from '../../types/WebElementProps';

export type DividerProps = WebElementProps<DividerContract>;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const dividerRule = {
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	display: 'block',
	borderTopWidth: 1,
	borderTopStyle: 'solid',
} as const;

const dividerLooks = {
	'default': {
		borderTopColor: '$rcx-stroke-extra-light',
	},
	'vertical': {
		width: 0,
		borderLeftWidth: 1,
		borderLeftStyle: 'solid',
		borderTopColor: '$rcx-stroke-extra-light',
		borderLeftColor: '$rcx-stroke-extra-light',
	},
	'danger': {
		borderColor: '$rcx-stroke-error',
	},
	'vertical-danger': {
		width: 0,
		borderLeftWidth: 1,
		borderLeftStyle: 'solid',
		borderColor: '$rcx-stroke-error',
	},
	'light': {
		borderColor: '$rcx-stroke-light',
	},
	'vertical-light': {
		width: 0,
		borderLeftWidth: 1,
		borderLeftStyle: 'solid',
		borderColor: '$rcx-stroke-light',
	},
	'medium': {
		borderColor: '$rcx-stroke-medium',
	},
	'vertical-medium': {
		width: 0,
		borderLeftWidth: 1,
		borderLeftStyle: 'solid',
		borderColor: '$rcx-stroke-medium',
	},
} as const;

const dividerSpacings = {
	'rule': {
		marginBlock: '$space.x8',
	},
	'vertical': {
		marginBlock: 0,
		marginInline: '$space.x8',
	},
	'vertical-small': {
		marginBlock: 0,
		marginInline: '$space.x4',
	},
	'flush': {
		margin: 0,
	},
} as const;

const dividerStretches = {
	fixed: {
		height: '$size.x20',
	},
	fill: {
		alignSelf: 'stretch',
		height: 'auto',
	},
} as const;

const dividerLabelled = {
	flexDirection: 'row',
	alignItems: 'center',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	display: 'flex',
	paddingInline: 0,
} as const;

const dividerBar = {
	flexDirection: 'row',
	alignItems: 'center',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	display: 'flex',
	justifyContent: 'flex-end',
	flexGrow: 1,
} as const;

const dividerLabel = {
	render: 'div',
	flexBasis: 'auto',
	whiteSpace: 'inherit',
	wordWrap: 'inherit',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	display: 'block',
	marginBlock: '$space.x8',
	paddingInline: '$space.x8',
} as const;

// end of generated

const RuleFrame = styled(View, {
	render: 'hr',
	...dividerRule,
	variants: {
		look: dividerLooks,
		spacing: dividerSpacings,
		stretch: dividerStretches,
	},
});

const LabelledFrame = styled(View, { render: 'div', ...dividerLabelled });

const BarFrame = styled(View, { render: 'div', ...dividerBar });

const LabelFrame = styled(Text, { ...dividerLabel });

const Divider = (props: DividerProps) => {
	const { variation, children, vertical, flush, small, stretch, className } = props;

	if (!children) {
		const modifiers = [
			variation === 'danger' && 'danger',
			flush && 'flush',
			variation === 'light' && 'light',
			vertical && small && 'small',
			vertical && stretch && 'stretch',
			vertical && 'vertical',
		]
			.filter(Boolean)
			.map((modifier) => ` rcx-divider--${modifier}`)
			.join('');

		const verticalLook = variation ? (`vertical-${variation}` as const) : 'vertical';
		const height = stretch ? 'fill' : 'fixed';

		return (
			<RuleFrame
				look={vertical ? verticalLook : (variation ?? 'default')}
				spacing={(flush && 'flush') || (vertical && (small ? 'vertical-small' : 'vertical')) || 'rule'}
				stretch={vertical ? height : undefined}
				className={prependClassName(className, `rcx-box rcx-box--full rcx-divider${modifiers}`)}
				render={<hr {...ariaAndDataAttributes(props)} ref={props.ref as WebHrRef} id={props.id} title={props.title} />}
			/>
		);
	}

	return (
		<LabelledFrame
			className={prependClassName(className, 'rcx-box rcx-box--full rcx-message-divider rcx-divider--labelled')}
			render={<div {...ariaAndDataAttributes(props)} ref={props.ref as WebDivRef} id={props.id} title={props.title} role='separator' />}
		>
			<BarFrame className='rcx-divider__bar' />
			<LabelFrame className='rcx-divider__wrapper'>{children}</LabelFrame>
			<BarFrame className='rcx-divider__bar' />
		</LabelledFrame>
	);
};

export default Divider;
